DESC='Del Manual del Coach: qué trabaja cada ejercicio, técnica paso a paso, errores, cues y escalado.'

def E(name, works, steps, errors, scale, no, si):
    st = steps + ['<b>Error:</b> ' + a + ' → <b>Corrige:</b> ' + b for a, b in errors] + ['<b>Escalado:</b> ' + scale]
    return L(name, 'Qué trabaja: ' + works, st, no, si)

